from collections import deque

def max_day_shift(n, clashes):
    near = [[] for _ in range(n)]
    for a, b in clashes:
        near[a].append(b)
        near[b].append(a)
    side = [-1] * n
    total = 0
    for s in range(n):
        if side[s] >= 0:
            continue
        side[s] = 0
        count = [1, 0]
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for w in near[u]:
                if side[w] < 0:
                    side[w] = 1 - side[u]
                    count[side[w]] += 1
                    queue.append(w)
                elif side[w] == side[u]:
                    return -1
        total += max(count)
    return total

